∀ {E : Type u_1}
  [inst : NormedAddCommGroup E] [inst_1 : InnerProductSpace ℝ E] [inst_2 : FiniteDimensional ℝ E]
  [inst_3 : MeasurableSpace E] [BorelSpace E] (x y : E) (τ : ℝ),
  0 < τ →
    have G := fun a => MeasureTheory.Measure.map (fun z => a + √τ • z) (ProbabilityTheory.stdGaussian E);
    have L := fun z => Real.exp (Inner.inner ℝ (x - y) (z - y) / τ - ‖x - y‖ ^ 2 / (2 * τ));
    Measurable L ∧
      (G x = (G y).withDensity fun z => ENNReal.ofReal (L z)) ∧
        (G x).AbsolutelyContinuous (G y) ∧ (G x).rnDeriv (G y) =ᵐ[G y] fun z => ENNReal.ofReal (L z)
